        };
    }

    fn deinit(s: *Sim) void {
        s.alloc.free(s.cidx);
        s.alloc.free(s.cidxp);
        s.alloc.free(s.shadow);
    }

    /// prompt.begin: a new chunk's picks, so its first pad runs (a new chunk re-pads).
    fn begin(s: *Sim, start: usize, n: usize, replay: usize) void {
        s.tracker.stale();
        s.sh_kk = null;
        s.start = start;
        s.n = n;
        s.floor = 0;
        s.replay = replay;
